"""L3 -- from objects to faces.

Same move as L1, different weights: BlazeFace instead of YOLO. It is a small,
fast, single-shot detector built to run on a phone, and it is looking for the
coarse arrangement of a face rather than anything resembling an identity.

Detection is not recognition. This module answers "is there a face here, and
where," and it has no notion of whose face it is. Keeping those two apart is
most of the privacy memo, and it is the difference between a room counter and
a surveillance system.
"""

from __future__ import annotations

from pathlib import Path

PROVIDED = Path(__file__).resolve().parent.parent / "provided"
FACE_MODEL = PROVIDED / "models" / "face_detection_short_range.tflite"



def load_face_detector(model_path=FACE_MODEL):
    """Return a face detector loaded from `model_path`.

    Hint: MediaPipe's Tasks API builds one from a `FaceDetectorOptions` holding
    a `BaseOptions` that takes the model path. Close it when you are done with
    it, or use it as a context manager.
    """
    # Lazy import: mediapipe is heavy, and importing the package must not
    # load a model or start anything.
    from mediapipe.tasks.python import BaseOptions
    from mediapipe.tasks.python.vision import (FaceDetector, FaceDetectorOptions,
                                               RunningMode)

    model_path = Path(model_path)
    if not model_path.is_file():
        raise FileNotFoundError(f"face model not found at {model_path}")
    options = FaceDetectorOptions(
        base_options=BaseOptions(model_asset_path=str(model_path)),
        running_mode=RunningMode.IMAGE,
    )
    return FaceDetector.create_from_options(options)


def detect_faces(detector, image_path):
    """Find every face in one image.

    Returns a list of (x1, y1, x2, y2) integer pixel boxes, top-left origin,
    in whatever order the detector reports them. No faces returns [].

    The detector reports a bounding box as an origin plus a width and height.
    The rest of this package expects corners. Convert here, once, rather than
    in every caller.
    """
    import mediapipe as mp

    # create_from_file decodes to SRGB, the format the Tasks API expects.
    image = mp.Image.create_from_file(str(image_path))
    return _boxes_from_result(detector.detect(image))


def detect_faces_array(detector, rgb):
    """Same as `detect_faces`, for an in-memory (H, W, 3) uint8 RGB array."""
    import mediapipe as mp
    import numpy as np

    rgb = np.ascontiguousarray(rgb, dtype=np.uint8)
    image = mp.Image(image_format=mp.ImageFormat.SRGB, data=rgb)
    return _boxes_from_result(detector.detect(image))


def _boxes_from_result(result):
    """Origin + width/height (MediaPipe) -> (x1, y1, x2, y2) integer corners."""
    boxes = []
    for det in result.detections:
        bb = det.bounding_box
        x1, y1 = int(bb.origin_x), int(bb.origin_y)
        boxes.append((x1, y1, x1 + int(bb.width), y1 + int(bb.height)))
    return boxes


def count_faces(detector, image_paths):
    """Return a dict mapping each path's filename to its number of faces.

    Built on `detect_faces`. Keys are filenames (not full paths), values are
    ints. This is the attendance counter in its smallest possible form.
    """
    return {Path(p).name: len(detect_faces(detector, p)) for p in image_paths}
